import{text,choice}from'../creative-kit/state.js?v=0.14.0';
export const FIELDS=['title','mechanism','strength','weakness','difference','assessment'];export const names={a:'A · First approach',b:'B · Improve a part',q:'Q · Change the mechanism'};
export function make(id='first',example='example'){const blank=()=>({title:'',mechanism:'',strength:'',weakness:'',difference:'',assessment:'',borrowed:[]});const w={id,problem:example==='blank'?'':'Help teams make useful decisions without another standing meeting.',answers:{a:blank(),b:blank(),q:blank()},phase:'generate',criteria:'',chosen:null,test:'',learn:''};if(example!=='blank'){Object.assign(w.answers.a,{title:'A weekly review meeting',mechanism:'Gather the people needed to compare options and decide together.',strength:'Shared context and visible accountability.',weakness:'People and decisions wait for a calendar slot.'});Object.assign(w.answers.b,{title:'A prepared review meeting',mechanism:'Send the question, evidence and options before the same weekly meeting.',strength:'More meeting time goes to the decision itself.',weakness:'The calendar is still the gate.',difference:'Improve readiness before the existing meeting.'});Object.assign(w.answers.q,{title:'An owner with an objection window',mechanism:'A named owner makes a reversible decision after a written window for objections.',strength:'Progress does not require synchronising calendars.',weakness:'Missing context or unclear ownership can hide disagreement.',difference:'Replace synchronous agreement with delegated authority and a bounded challenge period.'});w.criteria='Elapsed time to a useful decision; important objections surfaced; clarity of ownership.';}return w;}
export function validate(w){for(const key of Object.keys(names)){const a=w.answers?.[key];if(!a)throw Error('Keep all three answers.');FIELDS.forEach(f=>text(a[f]));if(!Array.isArray(a.borrowed)||a.borrowed.length>2)throw Error('Borrow at most two strengths.');const origins=new Set();for(const b of a.borrowed){choice(b.from,Object.keys(names));if(b.from===key||origins.has(b.from))throw Error('Borrow distinct strengths from other answers.');origins.add(b.from);text(b.text);if(typeof b.stale!=='boolean')throw Error('Invalid source review.');}}choice(w.phase,['generate','compare']);if(w.chosen!==null)choice(w.chosen,Object.keys(names));['criteria','test','learn'].forEach(f=>text(w[f]));return w;}
export function apply(w,a){if(a.type==='edit'){if(a.collection==='answers'){choice(a.item,Object.keys(names));choice(a.field,FIELDS);w.answers[a.item][a.field]=text(a.value);if(a.field==='strength')for(const answer of Object.values(w.answers))answer.borrowed.filter(b=>b.from===a.item).forEach(b=>b.stale=true);}else{choice(a.field,['criteria','test','learn']);w[a.field]=text(a.value);}}else if(a.type==='borrow'){choice(a.from,Object.keys(names));choice(a.to,Object.keys(names));if(a.from===a.to)throw Error('Borrow from a different approach.');const arr=w.answers[a.to].borrowed;const b={from:a.from,text:w.answers[a.from].strength,stale:false};const i=arr.findIndex(b=>b.from===a.from);if(i<0)arr.push(b);else arr[i]=b;}else if(a.type==='unborrow')w.answers[a.to].borrowed=w.answers[a.to].borrowed.filter(b=>b.from!==a.from);else if(a.type==='phase')w.phase=choice(a.phase,['generate','compare']);else if(a.type==='choose')w.chosen=choice(a.id,Object.keys(names));else throw Error('Unknown answer action.');}
export function markdown(w){return['# Three genuinely different answers','',w.problem,'',...Object.entries(w.answers).flatMap(([key,a])=>[`## ${names[key]}: ${a.title}${w.chosen===key?' · selected':''}`,'',...FIELDS.slice(1).flatMap(f=>[`**${f}**`,a[f]||'_Not written._','']),...a.borrowed.flatMap(b=>[`Borrowed from ${b.from.toUpperCase()}: ${b.text}${b.stale?' (source changed; recheck)':''}`,''])]),'## Comparison criteria',w.criteria,'','## Smallest test',w.test,'','## What would change my mind',w.learn].join('\n');}
